import { useState, useEffect } from 'react';
import axios from 'axios';

const STATUS_CFG = {
  draft:            { label: 'Draft',            cls: 'badge-gray'  },
  pending_manager:  { label: 'Pending Manager',  cls: 'badge-amber' },
  pending_hr_head:  { label: 'Pending HR Head',  cls: 'badge-amber' },
  approved:         { label: 'Approved',         cls: 'badge-green' },
  rejected:         { label: 'Rejected',         cls: 'badge-red'   },
  issued:           { label: 'Issued',           cls: 'badge-green' },
  withdrawn:        { label: 'Withdrawn',        cls: 'badge-red'   },
};

function GenerateModal({ employees, templates, onClose, onDone }) {
  const [step, setStep] = useState(1); // 1: pick employee+template, 2: extra fields
  const [form, setForm] = useState({
    employee_id: '', template_id: '',
    company_name: 'Acme Corp',
    hr_signatory_name: '', hr_signatory_designation: 'HR Manager',
    extra_fields: {}
  });
  const [error, setError]       = useState('');
  const [loading, setLoading]   = useState(false);

  const selectedTemplate = templates.find(t => t._id === form.template_id);
  const selectedEmployee = employees.find(e => e._id === form.employee_id);

  const generate = async () => {
    setError(''); setLoading(true);
    try {
      await axios.post('/api/letters/generate', form);
      onDone();
    } catch(e) {
      setError(e.response?.data?.error || 'Generation failed');
    } finally { setLoading(false); }
  };

  return (
    <div className="modal-overlay" onClick={e => e.target === e.currentTarget && onClose()}>
      <div className="modal" style={{ maxWidth: 560 }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 20 }}>
          <h2 className="modal-title" style={{ margin: 0 }}>Generate Offer Letter</h2>
          <div style={{ display: 'flex', gap: 6 }}>
            {[1,2].map(s => (
              <div key={s} style={{
                width: 28, height: 28, borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center',
                fontSize: 12, fontWeight: 600, fontFamily: 'var(--mono)',
                background: step === s ? 'var(--accent)' : step > s ? 'var(--green-dim)' : 'var(--surface-2)',
                color: step === s ? 'white' : step > s ? 'var(--green)' : 'var(--text-dim)',
                border: `1px solid ${step === s ? 'var(--accent)' : step > s ? 'var(--green)' : 'var(--border)'}`,
              }}>{s}</div>
            ))}
          </div>
        </div>

        {error && <div className="alert alert-error">{error}</div>}

        {step === 1 && (
          <>
            <div className="form-group">
              <label className="form-label">Employee *</label>
              <select value={form.employee_id} onChange={e => setForm({...form, employee_id: e.target.value})}>
                <option value="">Select employee...</option>
                {employees.map(emp => <option key={emp._id} value={emp._id}>{emp.name} — {emp.employee_id} — {emp.designation}</option>)}
              </select>
            </div>
            <div className="form-group">
              <label className="form-label">Template *</label>
              <select value={form.template_id} onChange={e => setForm({...form, template_id: e.target.value})}>
                <option value="">Select template...</option>
                {templates.map(t => <option key={t._id} value={t._id}>{t.name} (v{t.version})</option>)}
              </select>
            </div>

            {selectedEmployee && (
              <div style={{ background: 'var(--surface-2)', borderRadius: 'var(--radius)', padding: 12, marginBottom: 16, fontSize: 12 }}>
                <div style={{ fontSize: 10, fontFamily: 'var(--mono)', color: 'var(--text-dim)', textTransform: 'uppercase', marginBottom: 8 }}>Employee Preview</div>
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 8 }}>
                  {[['Name', selectedEmployee.name],['ID', selectedEmployee.employee_id],['Role', selectedEmployee.designation],['Dept', selectedEmployee.department],['CTC', '₹' + selectedEmployee.ctc],['Joining', selectedEmployee.joining_date]].map(([k,v]) => v ? (
                    <div key={k}><span style={{ color: 'var(--text-dim)' }}>{k}: </span><span style={{ fontWeight: 500 }}>{v}</span></div>
                  ) : null)}
                </div>
              </div>
            )}

            {selectedTemplate && (
              <div style={{ background: 'var(--surface-2)', borderRadius: 'var(--radius)', padding: 12, marginBottom: 16 }}>
                <div style={{ fontSize: 10, fontFamily: 'var(--mono)', color: 'var(--text-dim)', textTransform: 'uppercase', marginBottom: 8 }}>Template Placeholders</div>
                <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6 }}>
                  {(selectedTemplate.placeholders || []).map(p => <span key={p} className="badge badge-blue mono">{'{{'}{p}{'}}'}</span>)}
                </div>
              </div>
            )}

            <div className="modal-footer">
              <button className="btn btn-secondary" onClick={onClose}>Cancel</button>
              <button className="btn btn-primary" disabled={!form.employee_id || !form.template_id} onClick={() => setStep(2)}>Next →</button>
            </div>
          </>
        )}

        {step === 2 && (
          <>
            <div style={{ fontSize: 12, color: 'var(--text-muted)', marginBottom: 16 }}>
              These values fill any unresolved placeholders not covered by employee data.
            </div>
            <div className="form-row">
              <div className="form-group">
                <label className="form-label">Company Name</label>
                <input value={form.company_name} onChange={e => setForm({...form, company_name: e.target.value})} />
              </div>
              <div className="form-group">
                <label className="form-label">HR Signatory Name</label>
                <input value={form.hr_signatory_name} onChange={e => setForm({...form, hr_signatory_name: e.target.value})} placeholder="e.g. Priya Sharma" />
              </div>
            </div>
            <div className="form-group">
              <label className="form-label">HR Signatory Designation</label>
              <input value={form.hr_signatory_designation} onChange={e => setForm({...form, hr_signatory_designation: e.target.value})} />
            </div>
            <div className="modal-footer">
              <button className="btn btn-secondary" onClick={() => setStep(1)}>← Back</button>
              <button className="btn btn-primary" onClick={generate} disabled={loading}>
                {loading ? 'Generating...' : '◈ Generate Letter'}
              </button>
            </div>
          </>
        )}
      </div>
    </div>
  );
}

export default function LettersPage() {
  const [letters, setLetters]       = useState([]);
  const [employees, setEmployees]   = useState([]);
  const [templates, setTemplates]   = useState([]);
  const [loading, setLoading]       = useState(true);
  const [showGen, setShowGen]       = useState(false);
  const [submitTarget, setSubmit]   = useState(null);
  const [success, setSuccess]       = useState('');
  const [filterStatus, setFilter]   = useState('');

  const load = () => {
    setLoading(true);
    axios.get('/api/letters/' + (filterStatus ? `?status=${filterStatus}` : '')).then(r => setLetters(r.data)).finally(() => setLoading(false));
  };
  useEffect(() => { load(); }, [filterStatus]);
  useEffect(() => {
    axios.get('/api/employees/?status=active').then(r => setEmployees(r.data));
    axios.get('/api/templates/').then(r => setTemplates(r.data.filter(t => t.is_active)));
  }, []);

  const handleDone = () => { setShowGen(false); load(); setSuccess('Letter generated! Review and submit for approval.'); setTimeout(() => setSuccess(''), 5000); };

  const submitLetter = async () => {
    await axios.post(`/api/letters/${submitTarget._id}/submit`, {});
    setSubmit(null); load(); setSuccess('Submitted for manager approval.');
    setTimeout(() => setSuccess(''), 4000);
  };

  const download = (id, fmt) =>
    axios.get(`/api/letters/${id}/download?format=${fmt}`, { responseType: 'blob' })
      .then(r => { const url = URL.createObjectURL(r.data); const a = document.createElement('a'); a.href = url; a.download = `offer_letter.${fmt}`; a.click(); })
      .catch(() => alert('File not available on disk'));

  // ADD these functions inside LettersPage component:
  const handleIssue = async (id) => {
    await axios.post(`/api/letters/${id}/issue`, {});
    load(); setSuccess('Letter marked as issued.');
    setTimeout(() => setSuccess(''), 3000);
  };

  const [withdrawTarget, setWithdrawTarget] = useState(null);
  const [withdrawReason, setWithdrawReason] = useState('');

  const handleWithdraw = async () => {
    if (!withdrawReason.trim()) return alert('Reason is required');
    await axios.post(`/api/letters/${withdrawTarget._id}/withdraw`, { reason: withdrawReason });
    setWithdrawTarget(null); setWithdrawReason('');
    load(); setSuccess('Letter withdrawn.');
    setTimeout(() => setSuccess(''), 3000);
  };

  return (
    <div>
      <div className="page-header">
        <div>
          <h1 className="page-title">Offer Letters</h1>
          <p className="page-subtitle">{letters.length} letter{letters.length !== 1 ? 's' : ''}</p>
        </div>
        <button className="btn btn-primary" onClick={() => setShowGen(true)}>◈ Generate Letter</button>
      </div>

      {success && <div className="alert alert-success">{success}</div>}

      {/* Filter bar */}
      <div style={{ display: 'flex', gap: 8, marginBottom: 16 }}>
        {['', 'draft', 'pending_manager', 'pending_hr_head', 'approved', 'rejected'].map(s => (
          <button
            key={s}
            className={`btn btn-sm ${filterStatus === s ? 'btn-primary' : 'btn-secondary'}`}
            onClick={() => setFilter(s)}
            style={{ fontSize: 11 }}
          >
            {s === '' ? 'All' : STATUS_CFG[s]?.label}
          </button>
        ))}
      </div>

      <div className="card">
        {loading ? <div className="page-loading"><div className="spinner" /></div> : (
          <div className="table-wrap">
            <table>
              <thead>
                <tr>
                  <th>Employee</th><th>Version</th><th>Status</th><th>Generated</th><th>Approval Trail</th><th>Actions</th>
                </tr>
              </thead>
              <tbody>
                {letters.length === 0 ? (
                  <tr><td colSpan={6}><div className="empty-state">
                    <div className="empty-icon">◈</div>
                    <p>No offer letters yet — click Generate Letter to start</p>
                  </div></td></tr>
                ) : letters.map(l => {
                  const cfg = STATUS_CFG[l.status] || {};
                  return (
                    <tr key={l._id}>
                      <td>
                        <div style={{ fontWeight: 500 }}>{l.employee_name}</div>
                        <div className="mono text-muted text-sm">{l.employee_code}</div>
                      </td>
                      <td><span className="badge badge-gray mono">v{l.version}</span></td>
                      <td><span className={`badge ${cfg.cls}`}>{cfg.label}</span></td>
                      <td className="mono text-muted text-sm">{new Date(l.created_at).toLocaleDateString('en-IN')}</td>
                      <td>
                        <span style={{ fontSize: 11, color: 'var(--text-dim)' }}>
                          {(l.approval_history || []).length} action{l.approval_history?.length !== 1 ? 's' : ''}
                        </span>
                      </td>
                      <td>
                        <div style={{ display: 'flex', gap: 6 }}>
                          <button className="btn btn-sm btn-secondary" onClick={() => download(l._id, 'docx')}>↓ DOCX</button>
                          {['approved','issued'].includes(l.status) && (
                            <button className="btn btn-sm btn-secondary" onClick={() => download(l._id, 'pdf')}>↓ PDF</button>
                          )}
                          {l.status === 'draft' && (
                            <button className="btn btn-sm btn-primary" onClick={() => setSubmit(l)}>Submit →</button>
                          )}
                          {l.status === 'approved' && (
                            <button className="btn btn-sm btn-primary"
                              style={{ background: 'var(--green)', borderColor: 'var(--green)' }}
                              onClick={() => handleIssue(l._id)}>
                              ✓ Issue
                            </button>
                          )}
                          {!['issued','withdrawn','rejected'].includes(l.status) && (
                            <button className="btn btn-sm btn-secondary"
                              style={{ color: 'var(--red)', borderColor: 'var(--red-dim)' }}
                              onClick={() => setWithdrawTarget(l)}>
                              Withdraw
                            </button>
                          )}
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {showGen && <GenerateModal employees={employees} templates={templates} onClose={() => setShowGen(false)} onDone={handleDone} />}

      {submitTarget && (
        <div className="modal-overlay" onClick={e => e.target === e.currentTarget && setSubmit(null)}>
          <div className="modal" style={{ maxWidth: 400 }}>
            <h2 className="modal-title">Submit for Approval?</h2>
            <p style={{ color: 'var(--text-muted)', fontSize: 13, marginBottom: 16 }}>
              Offer letter for <strong style={{ color: 'var(--text)' }}>{submitTarget.employee_name}</strong> will enter the approval workflow.
            </p>
            <div style={{ background: 'var(--surface-2)', borderRadius: 'var(--radius)', padding: 12, marginBottom: 20, display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 10 }}>
              {['HR Draft','→','Manager','→','HR Head','→ ✓ Approved'].map((s,i) => (
                <span key={i} style={{ fontSize: 12, color: s.includes('✓') ? 'var(--green)' : s === '→' ? 'var(--border-bright)' : 'var(--text-muted)', fontFamily: 'var(--mono)' }}>{s}</span>
              ))}
            </div>
            <div className="modal-footer">
              <button className="btn btn-secondary" onClick={() => setSubmit(null)}>Cancel</button>
              <button className="btn btn-primary" onClick={submitLetter}>Submit</button>
            </div>
          </div>
        </div>
      )}

      {withdrawTarget && (
        <div className="modal-overlay" onClick={e => e.target === e.currentTarget && setWithdrawTarget(null)}>
          <div className="modal" style={{ maxWidth: 420 }}>
            <h2 className="modal-title">Withdraw Letter</h2>
            <p style={{ color: 'var(--text-muted)', fontSize: 13, marginBottom: 16 }}>
              Withdrawing <strong style={{ color: 'var(--text)' }}>{withdrawTarget.employee_name}</strong>'s
              offer letter. This action requires a mandatory reason and senior authorization.
            </p>
            <div className="form-group">
              <label className="form-label">Reason (mandatory) *</label>
              <textarea value={withdrawReason} onChange={e => setWithdrawReason(e.target.value)}
                rows={3} placeholder="e.g. Candidate declined offer / Role put on hold..." />
            </div>
            <div className="modal-footer">
              <button className="btn btn-secondary" onClick={() => setWithdrawTarget(null)}>Cancel</button>
              <button className="btn btn-danger" onClick={handleWithdraw}
                style={{ background: 'var(--red)' }}>Confirm Withdraw</button>
            </div>
          </div>
        </div>
      )}

    </div>
  );
}
